begin;
do $$declare a uuid;c uuid:=gen_random_uuid();p uuid:=gen_random_uuid();u uuid:=gen_random_uuid();m uuid:=gen_random_uuid();g uuid:=gen_random_uuid();l uuid:=gen_random_uuid();d jsonb:='{"title":"QA site access lesson","observation":"QA confirmed access prevented delay","cause":"","recommendation":"","applicability":"","status":"Draft","source":""}';reviewed jsonb;n integer:=0;begin
 select id into a from public.profiles where active and role='admin' order by id limit 1;if a is null then raise exception 'Administrator required';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
 insert into public.companies(id,name) values(c,'QA lessons register company');insert into public.projects(id,company_id,title) values(p,c,'QA lessons register project');
 insert into auth.users(id) values(u),(m);insert into public.profiles(id,name,role,company_id) values(u,'QA lesson client','client',c);insert into public.profiles(id,name,role) values(m,'QA lesson manager','team');insert into public.crm_teams(id,name) values(g,'QA lessons register team');insert into public.crm_memberships(user_id,role_id,team_id) values(m,'project_manager',g);insert into public.project_assignments(project_id,technician_id) values(p,m);
 perform set_config('request.jwt.claim.sub',m::text,true);execute 'set local role authenticated';perform public.save_project_lesson(l,null,p,d,'QA observed lesson');if not exists(select 1 from public.crm_project_lessons where id=l and version=1 and created_by=m) then raise exception 'Draft mismatch';end if;n:=n+1;
 perform public.save_project_lesson(l,null,p,d,'QA observed lesson');if (select count(*) from public.crm_project_lesson_history where lesson_id=l)<>1 then raise exception 'Retry duplicate';end if;n:=n+1;
 begin perform public.save_project_lesson(l,null,p,d||'{"title":"QA changed lesson"}','QA observed lesson');raise exception 'Changed retry allowed';exception when others then if sqlerrm is distinct from 'Lesson ID already used with different data' then raise;end if;end;n:=n+1;
 reviewed:=d||'{"recommendation":"QA confirm access before dispatch","applicability":"QA future visits","status":"Reviewed"}';
 begin perform public.save_project_lesson(l,1,p,reviewed,'QA forbidden self review');raise exception 'Manager review allowed';exception when others then if sqlerrm is distinct from 'Administrator reviews or archives lessons' then raise;end if;end;n:=n+1;
 perform public.save_project_lesson(l,1,p,reviewed||'{"status":"Draft"}','QA draft recommendation');if not exists(select 1 from public.crm_project_lessons where id=l and version=2) then raise exception 'Draft revision mismatch';end if;n:=n+1;
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.save_project_lesson(l,2,p,d||'{"status":"Reviewed"}','QA incomplete review');raise exception 'Incomplete review allowed';exception when others then if sqlerrm is distinct from 'Review requires recommendation and applicability' then raise;end if;end;n:=n+1;
 begin perform public.save_project_lesson(l,2,p,reviewed||'{"status":"Archived"}','QA skipped review');raise exception 'Draft archive allowed';exception when others then if sqlerrm is distinct from 'Review lesson before archiving' then raise;end if;end;n:=n+1;
 perform public.save_project_lesson(l,2,p,reviewed,'QA admin review');if not exists(select 1 from public.crm_project_lesson_history where lesson_id=l and revision=3 and actor_id=a and before_lesson->'details'->>'status'='Draft' and after_lesson->'details'->>'status'='Reviewed') then raise exception 'Review evidence mismatch';end if;n:=n+1;
 perform set_config('request.jwt.claim.sub',m::text,true);begin perform public.save_project_lesson(l,3,p,d,'QA forbidden withdrawal');raise exception 'Manager withdrawal allowed';exception when others then if sqlerrm is distinct from 'Administrator must revise or withdraw lesson review' then raise;end if;end;n:=n+1;
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.save_project_lesson(l,3,p,reviewed||'{"status":"Archived"}','QA archive reviewed lesson');if not exists(select 1 from public.crm_project_lessons where id=l and version=4 and details->>'status'='Archived') then raise exception 'Archive mismatch';end if;n:=n+1;
 begin perform public.save_project_lesson(l,4,p,d,'QA forbidden archive edit');raise exception 'Archive editable';exception when others then if sqlerrm is distinct from 'Archived lesson is immutable' then raise;end if;end;n:=n+1;
 begin update public.crm_project_lessons set version=99 where id=l;raise exception 'Direct mutation allowed';exception when insufficient_privilege then null;end;n:=n+1;
 begin delete from public.crm_project_lesson_history where lesson_id=l;raise exception 'History deletion allowed';exception when insufficient_privilege then null;end;n:=n+1;
 perform set_config('request.jwt.claim.sub',u::text,true);if exists(select 1 from public.crm_project_lessons where id=l) or exists(select 1 from public.crm_project_lesson_history where lesson_id=l) then raise exception 'Client read allowed';end if;n:=n+1;
 begin perform public.save_project_lesson(gen_random_uuid(),null,p,d,'QA forbidden client create');raise exception 'Client create allowed';exception when others then if sqlerrm is distinct from 'Assigned project manager access required' then raise;end if;end;n:=n+1;
 execute 'reset role';delete from public.project_assignments where project_id=p and technician_id=m;execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',m::text,true);if exists(select 1 from public.crm_project_lessons where id=l) then raise exception 'Revoked manager read allowed';end if;n:=n+1;
 begin perform public.save_project_lesson(gen_random_uuid(),null,p,d,'QA forbidden revoked create');raise exception 'Revoked create allowed';exception when others then if sqlerrm is distinct from 'Assigned project manager access required' then raise;end if;end;n:=n+1;
 execute 'reset role';if has_function_privilege('anon','public.save_project_lesson(uuid,integer,uuid,jsonb,text)','EXECUTE') then raise exception 'Anonymous RPC allowed';end if;n:=n+1;
 perform set_config('qa.lesson_result',jsonb_build_object('passed',true,'assertions',n,'fixtures_rollback',true)::text,true);
end$$;
select current_setting('qa.lesson_result')::jsonb as qa_result;
rollback;
